# Fetch and process API data
response = request_retry('GET', base_url + '/api/users')
users = response.json()

processed_users = []
for user in users:
    if user.get('active', False):
        processed_users.append({
            'name': user['name'],
            'email': user['email'],
            'external_id': user['id']
        })

bag['processed_users'] = processed_users
bag['total_active'] = len(processed_users)

# Safe API call with error handling
try:
    response = request_retry('GET', base_url + '/api/risky-endpoint')
    if response.status_code == 200:
        bag['success'] = True
        bag['data'] = response.json()
    else:
        bag['success'] = False
        bag['error'] = "HTTP " + str(response.status_code) + ": " + response.text
except Exception as e:
    bag['success'] = False
    bag['error'] = str(e)

# Use data from previous action in procedure
if 'partner_id' in bag:
    partner = env['res.partner'].browse(bag['partner_id'])

    # Create related record
    contact = env['res.partner'].create({
        'name': 'Contact Person',
        'parent_id': partner.id,
        'email': 'contact@example.com'
    })
bag['contact_id'] = contact.id
